def z13(eng):
  # propagate txn per stream.
  streams = defaultdict(list)
  last_txn = {}
  rows_txn = []
  for r in eng.rows:
    key = (r.get("log_host"), r.get("process_id"))
    t = _txn(r)
    if t is not None:
      last_txn[key] = t
    else:
      t = last_txn.get(key)
    rows_txn.append((r, t))
  g = defaultdict(list)
  for r, t in rows_txn:
    if t is not None:
      m = _msgs(r) & set(_RANK)
      if m:
        g[(r.get("log_host"), t)].append((r.epoch or 0, r.line_id, min(m, key=_RANK.get)))
  out = []
  for (host, t), evs in g.items():
    evs.sort()
    prev = None
    bad = False
    for _, _, m in evs:
      rank = _RANK[m]
      if prev is not None and rank < prev and m != "DHCPDISCOVER":
        bad = True
        break
      prev = rank
    if bad:
      out.append((host, t))
  return out

