def b5(eng):
  """Per client, average DISCOVER->ACK seconds. Only streams containing all of
  D/O/R/A qualify; deltas are paired per cycle (DISCOVER then next ACK) so that
  merged multi-cycle streams don't produce nonsense min-to-min gaps."""
  per_client = defaultdict(list)
  for (host, _), rows in _streams(eng).items():
    types = set().union(*[_msgs(r) for r in rows]) if rows else set()
    if not {"DHCPDISCOVER", "DHCPOFFER", "DHCPREQUEST", "DHCPACK"} <= types:
      continue
    rows = sorted(rows, key=lambda r: (r.epoch or 0, r.line_id))
    pend = None
    for r in rows:
      if _has(r, "DHCPDISCOVER") and r.epoch is not None:
        pend = r.epoch
      elif _has(r, "DHCPACK") and r.epoch is not None and pend is not None:
        per_client[host].append(r.epoch - pend)
        pend = None
  return [(h, round(sum(v) / len(v), 6)) for h, v in per_client.items() if v]

