def b13(eng):
  """Invalid DORA transitions per (client, txn). Messages with no txn inherit
  the latest explicit txn in the same process stream. Only D/O/R/A messages are
  considered; any consecutive pair outside the valid cycles is a violation."""
  seqs = defaultdict(list)
  for (host, _), rows in _streams(eng).items():
    rows = sorted(rows, key=lambda r: (r.epoch or 0, r.line_id))
    last_txn = None
    for r in rows:
      dora = sorted((m for m in _msgs(r) if m in _DORA_RANK),
                    key=lambda m: _DORA_RANK[m])
      t = _txn(r)
      if t is not None:
        last_txn = t
      txn = t if t is not None else last_txn
      if txn is None:
        continue
      for m in dora:
        seqs[(host, txn)].append(m)
