def b21(eng):
  """Early renewal: the first REQUEST following a bound within 25% of the lease
  time. One row per bound; a new DISCOVER starts a fresh cycle (not a renewal)."""
  out = set()
  for (host, _), rows in _streams(eng).items():
    rows = sorted(rows, key=lambda r: (r.epoch or 0, r.line_id))
    pending = None
    for r in rows:
      if r.get("action") == "bound" and r.get("lease_renewal_duration") is not None:
        try:
          T = float(str(r.get("lease_renewal_duration")).split()[0])
        except (TypeError, ValueError):
          pending = None
          continue
        pending = (r.epoch, r.get("assigned_ip"), T) if r.epoch is not None else None
      elif _has(r, "DHCPDISCOVER"):
        pending = None
      elif _has(r, "DHCPREQUEST") and r.epoch is not None and pending:
        bep, ip, T = pending
        if bep < r.epoch <= bep + 0.25 * T:
          out.add((host, ip, r.epoch - bep))
        elif r.epoch > bep + 0.25 * T:
          pending = None
  return list(out)
